from lib import *
S = SS('f58')
R = J('f58')
steps = [
    step("哪些文件名会自动转义(实测):page.html、page.htm、page.xml、page.xhtml、page.svg 渲染时 < > & 引号都被转义;page.txt、page.js、page.json 不转义;page.html.j2、page.jinja 与没有扩展名的 noext 也不转义 —— 只看最后的扩展名。render_template_string 总是转义。把模板命名成 .html.j2 或 .jinja 会悄悄关掉自动转义。", t=tl(S(1)), done=lidx(S(1), 'page.html ', 'page.xml', 'page.svg', 'render_template_string'), mark=lidx(S(1), 'page.txt', 'page.js', 'page.html.j2', 'page.jinja', 'noext'), kv=KV([['转义', '.html .htm .xml .xhtml .svg + render_template_string'], ['不转义', '.txt .js .json .html.j2 .jinja 无扩展名']], ['不转义'])),
    step("被转义的字符:输入 <>&'\"/\\` 变成 &lt;&gt;&amp;&#39;&#34;/\\`——只转义 < > & ' \" 五个,斜杠、反斜杠、反引号保持原样(反引号不转义意味着在某些旧浏览器的属性里需要自己小心)。", t=tl(S(2)), done=lidx(S(2), '输入'), kv=KV([['转义', "< > & ' \""], ['不转义', '/ \\ `']], ['不转义'])),
    step("同样的转义放在不同位置安全性不同:HTML 文本里 <script>alert(1)</script> 变成 &lt;script&gt;…(安全);带引号的属性里 \" onfocus=\"alert(1) 的引号被转成 &#34;(安全);但不带引号的属性 value={{ x }} 里 a onfocus=alert(1) 原样输出,多出一个事件属性(危险);href=\"{{ x }}\" 里 javascript:alert(1) 原样输出(危险);<script> 里的字符串变成 &#34;;alert(1);// 虽然没有逃逸但内容被 HTML 实体污染了;换成 |tojson 得到正确的 JS 字符串;<style> 里 red;} body{display:none 原样输出(CSS 注入);单引号属性里的单引号被转成 &#39;(安全)。", t=tl(S(3)), done=lidx(S(3), 'text   ', '带引号的属性', '单引号属性'), mark=lidx(S(3), '不带引号的属性', 'href(javascript:)', '<style> 里'), kv=KV([['带引号的属性 / 文本', '安全'], ['不带引号的属性', '危险'], ['href=javascript:', '不拦截'], ['<script> / <style>', '要用 tojson / 自己校验']], ['不带引号的属性'])),
    step("模板注入(SSTI):把用户输入拼进模板源码再渲染 render_template_string('<h1>你好 ' + name + '</h1>'),name={{ 7*7 }} 得到 <h1>你好 49</h1>,name={{ config.SECRET_KEY }} 直接得到 lab-secret(泄露了密钥)。正确写法是把输入当变量传进去 render_template_string('<h1>你好 {{ name }}</h1>', name=...):{{ 7*7 }} 原样显示成文本、不会被执行。永远不要把用户输入拼进模板字符串。", t=tl(S(4)), mark=lidx(S(4), '错误写法 name={{ 7*7 }}', '错误写法 name={{ config.SECRET_KEY }}'), done=lidx(S(4), '正确写法 name={{ 7*7 }}', '正确写法 name={{ config.SECRET_KEY }}'), kv=KV([['拼接进模板源码', '{{ 7*7 }} → 49;{{ config.SECRET_KEY }} → 泄露'], ['作为变量传入', '原样显示,不执行']], ['拼接进模板源码'])),
    step("关闭转义的两种方式:{{ x|safe }} 与 {% autoescape false %}{{ x }}{% endautoescape %} 都原样输出 <b>bold</b>;在不自动转义的文件(如 .txt)里可以用 {% autoescape true %} 局部开启,得到 &lt;b&gt;bold&lt;/b&gt;。|safe 的意思是「我保证这段已经安全」,对用户输入用它就是 XSS。", t=tl(S(5)), done=lidx(S(5), '|safe', 'autoescape false'), mark=lidx(S(5), 'autoescape true'), kv=KV([['|safe / autoescape false', '原样输出'], ['autoescape true', '局部开启转义']], ['|safe / autoescape false'])),
    step(f"tojson 过滤器:{{ x|tojson }} 输出的 JSON 里 < > & ' 被转成 \\u003c \\u003e \\u0026 \\u0027(例如 </script> 变成 \\u003c/script\\u003e),所以不会提前闭合 <script> 标签;返回值类型是 {R['tojson_type']}(已标记为安全,不会再被转义)。往 <script> 里放数据应该用 |tojson。", t=tl(S(6)), done=lidx(S(6), 'u003c', 'tojson 返回值的类型'), kv=KV([['tojson', "< > & ' → \\uXXXX"], ['返回类型', R['tojson_type']]], ['tojson'])),
]
